        ];
    }

    $chosen = $matches[0];
    $messages = [];
    $usage = ['input_tokens' => 0, 'output_tokens' => 0];
    foreach (jsonl($chosen) as $row) {
        if (($row['type'] ?? '') === 'user' && isset($row['message']['content'])) {
            $messages[] = ['role' => 'user', 'content' => extractText($row['message']['content'])];
        }
        if (($row['type'] ?? '') === 'assistant' && isset($row['message']['content'])) {
            $messages[] = ['role' => 'assistant', 'content' => extractText($row['message']['content'])];
            $u = $row['message']['usage'] ?? [];
            $usage['input_tokens'] += (int) ($u['input_tokens'] ?? 0);
            $usage['output_tokens'] += (int) ($u['output_tokens'] ?? 0);
            $usage['cache_read_tokens'] = (int) ($u['cache_read_input_tokens'] ?? 0);
            $usage['cache_write_tokens'] = (int) ($u['cache_creation_input_tokens'] ?? 0);
        }
    }

    $messagesJsonl = implode("\n", array_map(fn($m) => json_encode($m, JSON_UNESCAPED_SLASHES), $messages));

    return [
